  font-size: 16px;
  line-height: 1.5;
  color: var(--text);
  background:
    radial-gradient(1200px 600px at 10% -10%, rgba(122,162,255,0.15), transparent 60%),
    radial-gradient(900px 500px at 110% 20%, rgba(180,120,255,0.12), transparent 60%),
    linear-gradient(160deg, var(--bg-grad-1), var(--bg-grad-2));
  min-height: 100%;
}

.skip-link {
  position: absolute;
  left: 0.5rem;
  top: -3rem;
  background: var(--surface-2);
  color: var(--text);
  padding: 0.5rem 0.75rem;
  border-radius: 0.375rem;
  text-decoration: none;
  z-index: 100;
}
.skip-link:focus { top: 0.5rem; outline: 3px solid var(--focus); outline-offset: 2px; }

.page {
  display: flex;
  justify-content: center;
  padding: 2rem 1rem;
}

.card {
  width: 100%;
  max-width: 32rem;
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 0.875rem;
  padding: 1.75rem;
  box-shadow: 0 20px 60px rgba(0, 0, 0, 0.45);
}

.card__header { margin-bottom: 1.25rem; }

h1 {
  margin: 0 0 0.5rem;
  font-size: 1.625rem;
  letter-spacing: -0.01em;
}

.lede {
  margin: 0;
  color: var(--text-muted);
  font-size: 0.95rem;
}

.contact-form { display: flex; flex-direction: column; gap: 1.125rem; }

.form-field { display: flex; flex-direction: column; gap: 0.375rem; }

.form-field label {
  font-size: 0.9rem;
  font-weight: 600;
  color: var(--text);
}

.req { color: var(--accent); margin-left: 0.125rem; }
.optional { color: var(--text-muted); font-weight: 400; font-size: 0.85rem; }

.form-field input {
  width: 100%;
  padding: 0.7rem 0.85rem;
  font: inherit;
  color: var(--text);
  background: var(--surface-2);
  border: 1px solid var(--border-strong);
  border-radius: 0.5rem;
  transition: border-color 120ms ease, box-shadow 120ms ease, background 120ms ease;
}

.form-field input::placeholder { color: var(--text-muted); }

.form-field input:hover { border-color: #4a5594; }

.form-field input:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
  border-color: var(--accent);
  background: #232c50;
}

.form-field input:autofill,
.form-field input:-webkit-autofill {
  -webkit-text-fill-color: var(--text);
  -webkit-box-shadow: 0 0 0 1000px var(--surface-2) inset;
  caret-color: var(--text);
}

.help-text {
  margin: 0;
  font-size: 0.825rem;
  color: var(--text-muted);
}

.form-actions { margin-top: 0.25rem; }

.btn-primary {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 2.75rem;
  padding: 0.65rem 1.25rem;
  font: inherit;
  font-weight: 600;
  color: var(--accent-contrast);
  background: var(--accent);
  border: 1px solid var(--accent);
  border-radius: 0.5rem;
  cursor: pointer;
  transition: background 120ms ease, transform 80ms ease;
}

.btn-primary:hover { background: var(--accent-hover); border-color: var(--accent-hover); }
.btn-primary:active { transform: translateY(1px); }
.btn-primary:focus-visible { outline: 3px solid var(--focus); outline-offset: 2px; }

.form-status {
  margin: 0.25rem 0 0;
  min-height: 1.25rem;
  font-size: 0.9rem;
  color: var(--text-muted);
}
.form-status.is-success { color: #9ce0a8; }
.form-status.is-error { color: var(--error); }

@media (forced-colors: active) {
  .form-field input,
  .btn-primary,
  .card { border: 1px solid CanvasText; }
  .btn-primary { background: ButtonFace; color: ButtonText; }
  *:focus-visible { outline: 3px solid Highlight; }
}

@media (prefers-reduced-motion: reduce) {
  * { transition: none !important; }
}
