  const form = document.getElementById("contact-form");
  const status = document.getElementById("form-status");
  if (!form) return;

  const fields = [
    {
      input: document.getElementById("full-name"),
      validate: (v) => v.trim().length > 0,
      error: "Error: Enter your full name.",
    },
    {
      input: document.getElementById("email"),
      validate: (v) => /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(v.trim()),
      error: "Error: Enter a valid email like name@example.com.",
    },
  ];

  function setError(input, message) {
    const wrapper = input.closest(".form-field");
    let errorEl = wrapper.querySelector(".error-text");
    if (!errorEl) {
      errorEl = document.createElement("p");
      errorEl.className = "error-text";
      errorEl.id = `${input.id}-error`;
      errorEl.style.color = "var(--error)";
      errorEl.style.fontSize = "0.85rem";
      errorEl.style.margin = "0";
      wrapper.appendChild(errorEl);
    }
    errorEl.textContent = message;
    input.setAttribute("aria-invalid", "true");
    const describedBy = (input.getAttribute("aria-describedby") || "")
      .split(/\s+/)
      .filter(Boolean);
    if (!describedBy.includes(errorEl.id)) {
      describedBy.push(errorEl.id);
      input.setAttribute("aria-describedby", describedBy.join(" "));
    }
  }

  function clearError(input) {
    const wrapper = input.closest(".form-field");
    const errorEl = wrapper.querySelector(".error-text");
    input.removeAttribute("aria-invalid");
    if (errorEl) {
      const describedBy = (input.getAttribute("aria-describedby") || "")
        .split(/\s+/)
        .filter((id) => id && id !== errorEl.id);
      if (describedBy.length) {
        input.setAttribute("aria-describedby", describedBy.join(" "));
      } else {
        input.removeAttribute("aria-describedby");
      }
      errorEl.remove();
    }
  }

  fields.forEach(({ input, validate, error }) => {
    input.addEventListener("input", () => {
      if (input.getAttribute("aria-invalid") === "true" && validate(input.value)) {
        clearError(input);
      }
    });
    input.addEventListener("blur", () => {
      if (input.getAttribute("aria-invalid") === "true" && !validate(input.value)) {
        setError(input, error);
      }
    });
  });

  form.addEventListener("submit", (event) => {
    event.preventDefault();
    let firstInvalid = null;
    fields.forEach(({ input, validate, error }) => {
      if (validate(input.value)) {
        clearError(input);
      } else {
        setError(input, error);
        if (!firstInvalid) firstInvalid = input;
      }
    });

    status.classList.remove("is-success", "is-error");
    if (firstInvalid) {
      status.textContent = "Please fix the highlighted fields and try again.";
      status.classList.add("is-error");
      firstInvalid.focus();
      return;
    }

    status.textContent = "Thanks! Your message has been sent. We'll be in touch soon.";
    status.classList.add("is-success");
    form.reset();
  });
})();
